import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { IsNull, type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { TagsEntity } from "#/modules/filesystem/schema/entities/tags.entity.ts";
import * as Tags from "#/modules/filesystem/schema/types/tags/index.ts";

/**
 * Repository of Tags: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class TagsRepository
  extends EntityRepository<
    TagsEntity,
    Tags.Types.TagsSortableField,
    Tags.Types.TagsEditableField,
    Tags.Types.TagsSelectableField,
    Tags.Types.ITagsCreatable
  >
  implements IUpdatableRepository<TagsEntity, Tags.Types.ITagsUpdatable>
{
  constructor(
    @InjectRepository(TagsEntity)
    repository: Repository<TagsEntity>,
  ) {
    super(repository, Tags.Config.TAGS_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(id: string, data: Tags.Types.ITagsUpdatable): Promise<TagsEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the tags with this code (unique). */
  async findByCode(code: NonNullable<TagsEntity["code"]>): Promise<TagsEntity | null> {
    return await this.findOne({ code, deletedAt: IsNull() });
  }
}
